custom_css:
/* ── Modernized Web Form Style ── */

/* 1. Global Container & Background */
.page_content { 
    max-width: 100% !important; 
}

.web-form-container {
    max-width: 100% !important; /* Form shouldn't be TOO wide for readability */
}

/* 2. Inputs & Controls */
.control-value, .attached-file {
    height: 42px !important; /* Slightly taller for modern feel */
    background: #ffffff !important;
    border: 1.5px solid #e5e7eb !important; /* Lighter, thicker border */
    border-radius: 8px !important; /* Rounded corners */
    padding: 0 12px !important;
    transition: border-color 0.2s, box-shadow 0.2s !important;
    font-size: 14px !important;
    color: #374151 !important;
    padding: 8px 12px !important;
}

/* Interactive Focus State */
.control-value:focus, .attached-file:focus {
    border-color: #3b82f6 !important;
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1) !important;
    outline: none !important;
}

.form-control {
    height: 42px !important; /* Slightly taller for modern feel */
    background: #f8fafc !important;
    border: 1.5px solid #e5e7eb !important; /* Lighter, thicker border */
    border-radius: 8px !important; /* Rounded corners */
    transition: border-color 0.2s, box-shadow 0.2s !important;
    font-size: 14px !important;
    color: #374151 !important;
}
/* 3. Headers & Typography */
.section-head {
    color: #2931cc !important; /* Deep slate instead of royal blue */
    font-weight: 700 !important;
    font-size: 1.25rem !important;
    margin-bottom: 20px !important;
    padding-bottom: 8px;
}

/* 4. Buttons (Next/Previous) */
.btn-next, .btn-previous {
    height: 40px !important;
    padding: 0 30px !important;
    border-radius: 8px !important;
    font-weight: 600 !important;
    border: none !important;
    transition: transform 0.1s, background-color 0.2s !important;
    cursor: pointer !important;
}

.btn-next , .submit-btn {
    background: #2563eb !important; /* Modern Primary Blue */
    color: white !important;
}

.btn-next , .submit-btn:hover {
    background: #1d4ed8 !important;
}

.btn-previous {
    background: #ffffff !important;
    border: 1px solid #d1d5db !important;
    color: #4b5563 !important;
}

.btn-previous:hover {
    background: #f3f4f6 !important;
}

/* 5. Special Elements */
.not-saved-badge { /* If you have a class for that 'Not Saved' text */
    background-color: #fef3c7 !important;
    color: #92400e !important;
    padding: 2px 8px !important;
    border-radius: 99px !important;
    font-size: 12px !important;
    font-weight: 500 !important;
}
.web-form-head {
    padding-bottom: 1.25rem !important;
    border-bottom: 0px solid var(--dark-border-color) !important;
}
.web-form-header {
    border-bottom: 1px solid var(--dark-border-color) !important;
}
.control-input > textarea {
    height: 170px;
}
.container {
    padding:none !important;
    min-width: 100% !important
}
.form-grid-container , .form-grid , .column-limit-reached  {
    overflow-x: auto !important;
}

client_script:
frappe.web_form.after_load = () => {
    if (window.location.pathname.endsWith("/new") && frappe.session.user) {
        let current_path = window.location.href;
        window.location.href = current_path.replace("/new", "/" + frappe.session.user);
    }
}

// Mask document name from URL
(function() {
    var path = window.location.pathname;
    if (path.indexOf('/foundations-for-a-legal-education/') === 0) {
        history.replaceState(null, '', '/foundations-for-a-legal-education');
    }
})();

$(document).ready(function () {

    // =========================================================================
