            '  transform:        translateY(-1px)              !important;',
            '  box-shadow:       0 2px 8px rgba(139,0,0,0.15) !important;',
            '  color:            #8B0000                      !important;',
            '}',

            '.web-form-footer .btn-secondary,',
            '.web-form-footer button.btn-secondary,',
            '.page-actions .btn-secondary,',
            '.form-footer .btn-secondary {',
            '  background-color: #ffffff             !important;',
            '  color:            #555555             !important;',
            '  border:           2px solid #cccccc   !important;',
            '  box-shadow:       none                !important;',
            '}',
            '.web-form-footer .btn-secondary:hover,',
            '.page-actions .btn-secondary:hover,',
            '.form-footer .btn-secondary:hover {',
            '  background-color: #f5f5f5             !important;',
            '  border-color:     #aaaaaa             !important;',
            '  transform:        translateY(-1px)    !important;',
            '  color:            #333333             !important;',
            '}',

            '.web-form-footer .btn-danger,',
            '.web-form-footer button.btn-danger,',
            '.page-actions .btn-danger,',
            '.form-footer .btn-danger {',
            '  background-color: #ffffff           !important;',
            '  color:            #cc0000           !important;',
            '  border:           2px solid #cc0000 !important;',
            '  box-shadow:       none              !important;',
            '}',
            '.web-form-footer .btn-danger:hover,',
            '.page-actions .btn-danger:hover,',
            '.form-footer .btn-danger:hover {',
            '  background-color: #fff0f0                      !important;',
            '  transform:        translateY(-1px)              !important;',
            '  box-shadow:       0 2px 8px rgba(204,0,0,0.15) !important;',
            '  color:            #aa0000                      !important;',
            '}',

            // FIX 3: CSS backstop — hide Discard button regardless of how Frappe renders it
            '#fle-discard-hidden,',
            '.web-form-footer button#fle-discard-hidden,',
            '.page-actions button#fle-discard-hidden,',
            '.form-footer button#fle-discard-hidden {',
            '  display:        none    !important;',
            '  visibility:     hidden  !important;',
            '  pointer-events: none    !important;',
            '  width:          0       !important;',
            '  height:         0       !important;',
            '  margin:         0       !important;',
            '  padding:        0       !important;',
            '  overflow:       hidden  !important;',
            '}',

            '.fle-check-row {',
            '  display:        flex        !important;',
            '  flex-direction: row         !important;',
            '  align-items:    center      !important;',
            '  flex-wrap:      nowrap      !important;',
            '  gap:            8px         !important;',
            '  margin:         0           !important;',
            '  padding:        0           !important;',
            '  cursor:         pointer;',
            '}',
            '.fle-check-row input[type="checkbox"] {',
            '  display:        inline-block !important;',
            '  flex-shrink:    0            !important;',
            '  width:          15px         !important;',
            '  height:         15px         !important;',
            '  min-width:      15px         !important;',
            '  min-height:     15px         !important;',
            '  margin:         0            !important;',
            '  padding:        0            !important;',
            '  float:          none         !important;',
            '  position:       relative     !important;',
            '  top:            0            !important;',
            '  vertical-align: middle       !important;',
            '  cursor:         pointer;',
            '}',
            '.fle-check-row .fle-check-label {',
            '  display:        inline   !important;',
            '  vertical-align: middle   !important;',
            '  line-height:    1.5      !important;',
            '  margin:         0        !important;',
            '  padding:        0        !important;',
            '  font-family:    inherit  !important;',
            '  font-size:      inherit  !important;',
            '  color:          inherit  !important;',
            '  cursor:         pointer;',
            '}',

            '[data-fieldname="i_hereby_consent_to_this_declaration"] .fle-chk-original-hidden {',
            '  display: none !important;',
            '}',

            '[data-fieldname="i_hereby_consent_to_this_declaration"] {',
            '  margin:  0 !important;',
            '  padding: 0 !important;',
            '}',

            '.fle-check-row {',
            '  margin: 0 !important;',
            '}',

            // Reduce page title (FLE-2026-XXXX) size to match header
            '.web-form-container h1,',
            '.web-form-container h2,',
            '.web-form-container h3,',
            '.web-form-container .title,',
            '.web-form-wrapper  h1,',
            '.web-form-wrapper  h2,',
            '.web-form-wrapper  h3,',
            '.web-form-wrapper  .title,',
            '.page-container    h1,',
            '.page-container    h2,',
            '.page-container    h3,',
            'h3.title,',
            '.title {',
            '  font-size:   20px    !important;',
            '  font-weight: 700     !important;',
            '  line-height: 1.3     !important;',
            '  margin:      0 0 8px !important;',
            '}'

        ].join('\n');
        (document.head || document.documentElement).appendChild(style);
    })();

    // =========================================================================
    //  SHRINK PAGE TITLE (JS fallback — CSS alone may miss inline-styled nodes)
    // =========================================================================

    function shrinkPageTitle() {
        document.querySelectorAll('h1, h2, h3, .title').forEach(function (el) {
            var txt = (el.textContent || '').trim();
            // Target only the document-name heading (e.g. "FLE-2026-0119")
            if (/^FLE-\d{4}-\d+$/.test(txt)) {
                el.style.setProperty('font-size',   '20px',   'important');
                el.style.setProperty('font-weight', '700',    'important');
                el.style.setProperty('line-height', '1.3',    'important');
                el.style.setProperty('margin',      '0 0 8px','important');
            }
        });
    }

    // Run at boot and after DOM settles
    shrinkPageTitle();
    setTimeout(shrinkPageTitle, 500);
    setTimeout(shrinkPageTitle, 1500);

    // =========================================================================
    //  USER IDENTITY
    // =========================================================================

    function getUserEmail() {
        var params   = new URLSearchParams(window.location.search);
        var urlEmail = params.get('email_address') || params.get('email') || '';
        if (urlEmail && urlEmail.indexOf('@') !== -1) return urlEmail.toLowerCase().trim();

        var emailWrapper = document.querySelector('[data-fieldname="email_address"]');
        if (emailWrapper) {
            var emailInp = emailWrapper.querySelector('input.input-with-feedback');
            if (emailInp && emailInp.value && emailInp.value.indexOf('@') !== -1) {
                return emailInp.value.toLowerCase().trim();
            }
        }

        if (window.frappe && frappe.session && frappe.session.user &&
            frappe.session.user !== 'Guest') {
            return frappe.session.user.toLowerCase().trim();
        }
        return '';
    }

    function getDraftKey() {
        var email = getUserEmail();
        if (!email) return null;
        return DRAFT_KEY_PREFIX + email.replace(/[^a-z0-9@._-]/g, '_');
    }

    // =========================================================================
    //  FIELD TYPE MAP
    //  FIX 1: Added 'relationship_with_the_candidate' as 'select'
    // =========================================================================

    var TYPED_FIELDS = {
        'candidate_gender'                    : 'select',
        'candidate_state'                     : 'select',
        'candidates_state'                    : 'select',
        'country_of_residence'                : 'select',
        'where_did_you_hear'                  : 'select',
        'candidate_current_occupation'        : 'select',
        'last_class_attended'                 : 'select',
        'latest_board_attended'               : 'select',
        'year_of_passing'                     : 'select',
        'relationship_with_candidate'         : 'select',
        'candidate_nationality'               : 'link',
        'i_hereby_consent_to_this_declaration': 'check',
        'declaration_consent'                 : 'check',
        'id_card_scan'                        : 'attach',
        'candidate_photo'                     : 'attach'
    };

    var SKIP_FIELDS = { '__newname': true, 'amended_from': true };

    // =========================================================================
    //  REQUIRED FIELDS FOR "PROCEED TO PAY"
    // =========================================================================

    var REQUIRED_FOR_PAY = [
        'email_address',
        'candidate_name',
        'candidate_dob',
        'candidate_gender',
        'candidate_contact_number',
        'country_of_residence',
        'city',
        'candidates_state',
        'where_did_you_hear',
        'candidate_current_occupation',
        'last_class_attended',
        'latest_board_attended',
        'year_of_passing',
        'id_card_scan',
        'candidate_photo',
        'declaration_consent'
    ];

    // =========================================================================
    //  STORAGE
    // =========================================================================

    var Store = {
        save: function (data) {
            var key = getDraftKey();
            if (!key) { console.warn('[Draft] No user key — cannot save.'); return false; }
            try { localStorage.setItem(key, JSON.stringify(data)); return true; }
            catch (e) { console.error('[Draft] save error:', e); return false; }
        },
        load: function () {
            var key = getDraftKey();
            if (!key) return null;
            try {
                var r = localStorage.getItem(key);
                return r ? JSON.parse(r) : null;
            } catch (e) { return null; }
        }
    };

    // =========================================================================
    //  FIELD DISCOVERY
    //  FIX 2a: Detect Attach / Attach Image fields even when they have no
    //          standard input.input-with-feedback in the DOM
    // =========================================================================

    function discoverFields() {
        var result = [], seen = {};
        document.querySelectorAll('[data-fieldname]').forEach(function (wrapper) {
            var fn = wrapper.getAttribute('data-fieldname');
            if (!fn || seen[fn] || SKIP_FIELDS[fn]) return;

            var explicitType = TYPED_FIELDS[fn];

            // FIX 2a — detect attach fields via Frappe fieldtype metadata
            if (!explicitType) {
                try {
                    if (window.frappe && frappe.web_form &&
                        frappe.web_form.fields_dict &&
                        frappe.web_form.fields_dict[fn] &&
                        frappe.web_form.fields_dict[fn].df) {
                        var ft = frappe.web_form.fields_dict[fn].df.fieldtype;
                        if (ft === 'Attach' || ft === 'Attach Image') {
                            explicitType = 'attach';
                        }
                    }
                } catch (e) { /* ignore */ }
            }

            // FIX 2a — detect attach fields via DOM markers as fallback
            if (!explicitType && (
                wrapper.querySelector('.attachment-row, [data-file-name], .attached-file, .btn-attach, .attach-btn') ||
                (wrapper.classList &&
                    (wrapper.classList.contains('frappe-control-attach') ||
                     wrapper.classList.contains('frappe-control-attach-image')))
            )) {
                explicitType = 'attach';
            }

            var chk = wrapper.querySelector('input[type="checkbox"]');
            if (!explicitType && chk) explicitType = 'check';

            var hasInput = wrapper.querySelector(
                'input.input-with-feedback, select, textarea, input[type="checkbox"]'
            );

            // Attach fields may have no standard input — still include them
            if (!hasInput && explicitType !== 'attach') return;

            seen[fn] = true;
            result.push({ fieldname: fn, type: explicitType || 'text' });
        });
        return result;
    }

    // =========================================================================
    //  READ FIELD
    //  FIX 2b: readAttachField reads file URL from frappe.web_form.doc first,
    //          then fields_dict, then DOM anchor, then any input
    // =========================================================================

    function readSelectField(wrapper) {
        var fn = wrapper.getAttribute('data-fieldname');
        // 1. Frappe model — most reliable (always up-to-date after user picks)
        try {
            if (window.frappe && frappe.web_form) {
                if (frappe.web_form.doc) {
                    var dv = frappe.web_form.doc[fn];
                    if (dv && dv.toString().trim()) return dv.toString().trim();
                }
                var gv = frappe.web_form.get_value(fn);
                if (gv && gv.toString().trim()) return gv.toString().trim();
            }
        } catch (e) { /* ignore */ }
        // 2. Native <select> element
        var sel = wrapper.querySelector('select');
        if (sel && sel.value && sel.value.trim()) return sel.value.trim();
        // 3. Frappe custom input (awesomplete / link-style select)
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp && inp.value && inp.value.trim()) return inp.value.trim();
        // 4. Read-only display spans
        var ldi = wrapper.querySelector('.like-disabled-input');
        if (ldi && ldi.textContent && ldi.textContent.trim()) return ldi.textContent.trim();
        var optSel = wrapper.querySelector('[data-label]');
        if (optSel) {
            var lbl = optSel.getAttribute('data-label') || '';
            if (lbl.trim()) return lbl.trim();
        }
        return '';
    }

    function readAttachField(fieldname) {
        // 1. Frappe doc — most reliable, always set after upload
        try {
            if (window.frappe && frappe.web_form && frappe.web_form.doc) {
                var dv = frappe.web_form.doc[fieldname];
                if (dv && typeof dv === 'string' && dv.trim()) return dv.trim();
            }
        } catch (e) { /* ignore */ }

        // 2. fields_dict get_value
        try {
            if (window.frappe && frappe.web_form &&
                frappe.web_form.fields_dict &&
                frappe.web_form.fields_dict[fieldname]) {
                var val = frappe.web_form.get_value(fieldname);
                if (val && typeof val === 'string' && val.trim()) return val.trim();
            }
        } catch (e) { /* ignore */ }

        // 3. DOM: attachment link or data-file-name attribute
        var wrapper = document.querySelector('[data-fieldname="' + fieldname + '"]');
        if (wrapper) {
            var anchor = wrapper.querySelector(
                '.attachment-row a, .attached-file a, [data-file-name]'
            );
            if (anchor) {
                var href = anchor.getAttribute('href') ||
                           anchor.getAttribute('data-file-name') ||
                           anchor.textContent.trim();
                if (href && href.trim()) return href.trim();
            }
            // 4. Any plain input inside the wrapper
            var inp = wrapper.querySelector('input');
            if (inp && inp.value && inp.value.trim()) return inp.value.trim();
        }
        return '';
    }

    function readField(cfg) {
        var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
        if (!wrapper) return '';

        if (cfg.type === 'attach') return readAttachField(cfg.fieldname);   // FIX 2b

        if (cfg.type === 'check') {
            var chk = wrapper.querySelector('input[type="checkbox"]');
            return chk ? (chk.checked ? '1' : '0') : '';
        }

        if (cfg.type === 'select') return readSelectField(wrapper);

        if (cfg.type === 'link') {
            // 1. Frappe model — primary source for link fields
            try {
                if (window.frappe && frappe.web_form) {
                    if (frappe.web_form.doc) {
                        var linkDoc = frappe.web_form.doc[cfg.fieldname];
                        if (linkDoc && linkDoc.toString().trim()) return linkDoc.toString().trim();
                    }
                    var linkGv = frappe.web_form.get_value(cfg.fieldname);
                    if (linkGv && linkGv.toString().trim()) return linkGv.toString().trim();
                }
            } catch (e) { /* ignore */ }
            // 2. DOM awesomplete input fallback
            var inpLink = wrapper.querySelector('input.input-with-feedback');
            if (inpLink && inpLink.value && inpLink.value.trim()) return inpLink.value.trim();
            return '';
        }

        var inp3 = wrapper.querySelector('input.input-with-feedback');
        if (inp3 && inp3.value && inp3.value.trim()) return inp3.value.trim();

        var ta = wrapper.querySelector('textarea');
        if (ta && ta.value && ta.value.trim()) return ta.value.trim();

        return '';
    }

    // =========================================================================
    //  NATIVE VALUE SETTER
    // =========================================================================

    function nativeSet(inp, val) {
        try {
            var desc = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value');
            if (desc && desc.set) { desc.set.call(inp, val); return; }
        } catch (e) { /* fall through */ }
        inp.value = val;
    }

    // =========================================================================
    //  EVENT HELPERS
    // =========================================================================

    function fire(el, types) {
        types.forEach(function (t) {
            el.dispatchEvent(new Event(t, { bubbles: true }));
        });
    }

    function fireChange(el) {
        el.dispatchEvent(new Event('change', { bubbles: true }));
    }

    // =========================================================================
    //  WRITE FIELD
    //  FIX 2c: Added 'attach' branch — restores file URL via Frappe API
    // =========================================================================

    function writeField(cfg, val, isRestore) {
        if (val === '' || val === null || val === undefined) return false;
        var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
        if (!wrapper) return false;
        if (cfg.type === 'attach') return writeAttachField(cfg.fieldname, val);  // FIX 2c
        if (cfg.type === 'check')  return writeCheck(wrapper, val);
        if (cfg.type === 'select') return writeSelect(wrapper, val, isRestore);
        if (cfg.type === 'link')   return writeLink(wrapper, val, isRestore);
        return writeText(wrapper, val, isRestore);
    }

    // FIX 2c: Set file URL in Frappe model and refresh field UI
    function writeAttachField(fieldname, val) {
        try {
            if (window.frappe && frappe.web_form) {
                if (frappe.web_form.doc) {
                    frappe.web_form.doc[fieldname] = val;
                }
                frappe.web_form.set_value(fieldname, val);
                setTimeout(function () {
                    try {
                        if (frappe.web_form.fields_dict &&
                            frappe.web_form.fields_dict[fieldname]) {
                            frappe.web_form.fields_dict[fieldname].set_value(val);
                        }
                        frappe.web_form.refresh_field(fieldname);
                    } catch (e) { /* ignore */ }
                }, 300);
                console.log('[Draft] ✅ Attach field set:', fieldname, '->', val);
                return true;
            }
        } catch (e) {
            console.warn('[Draft] writeAttachField failed:', fieldname, e);
        }
        return false;
    }

    function writeCheck(wrapper, val) {
        var chk = wrapper.querySelector('input[type="checkbox"]');
        if (!chk) return false;
        var shouldCheck = (val === '1' || val === true || val === 'true');
        if (chk.checked !== shouldCheck) { chk.checked = shouldCheck; fireChange(chk); }
        return true;
    }

    function writeSelect(wrapper, val, isRestore) {
        var fn      = wrapper.getAttribute('data-fieldname');
        var sel     = wrapper.querySelector('select');
        var matched = false;

        // 1. Frappe set_value — updates the model (critical for select/link-style fields)
        try {
            if (window.frappe && frappe.web_form) {
                if (frappe.web_form.doc) frappe.web_form.doc[fn] = val;
                frappe.web_form.set_value(fn, val);
                setTimeout(function () {
                    try { frappe.web_form.refresh_field(fn); } catch (e) { /* ignore */ }
                }, 300);
                console.log('[Draft] ✅ Select field set:', fn, '->', val);
            }
        } catch (e) { console.warn('[Draft] writeSelect frappe error:', fn, e); }

        // 2. Native <select> element
        if (sel) {
            for (var i = 0; i < sel.options.length; i++) {
                var o = sel.options[i];
                if (o.value.trim().toLowerCase() === val.toLowerCase() ||
                    o.text.trim().toLowerCase()  === val.toLowerCase()) {
                    sel.selectedIndex = i;
                    matched = true;
                    break;
                }
            }
            if (matched) fireChange(sel);
        }

        // 3. Frappe awesomplete / custom input
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp) {
            nativeSet(inp, val);
            if (isRestore) fireChange(inp);
            else fire(inp, ['input', 'change']);
        }

        return matched || !!inp || true;
    }

    function writeLink(wrapper, val, isRestore) {
        var fn = wrapper.getAttribute('data-fieldname');
        // 1. Frappe set_value — updates model + UI (works even without DOM input)
        try {
            if (window.frappe && frappe.web_form) {
                if (frappe.web_form.doc) frappe.web_form.doc[fn] = val;
                frappe.web_form.set_value(fn, val);
                setTimeout(function () {
                    try { frappe.web_form.refresh_field(fn); } catch (e) { /* ignore */ }
                    hideAwesomplete(wrapper);
                }, 300);
                console.log('[Draft] ✅ Link field set:', fn, '->', val);
            }
        } catch (e) { console.warn('[Draft] writeLink frappe error:', fn, e); }
        // 2. Also set DOM input so user sees the value immediately
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp) {
            nativeSet(inp, val);
            if (isRestore) fireChange(inp);
            else fire(inp, ['input', 'change']);
            hideAwesomplete(wrapper);
            setTimeout(function () { hideAwesomplete(wrapper); }, 100);
            setTimeout(function () { hideAwesomplete(wrapper); }, 300);
        }
        return true;
    }

    function writeText(wrapper, val, isRestore) {
        var inp = wrapper.querySelector('input.input-with-feedback');
        if (inp) {
            nativeSet(inp, val);
            if (!isRestore) fire(inp, ['input', 'change']);
            else fireChange(inp);
            return true;
        }
        var ta = wrapper.querySelector('textarea');
        if (ta) {
            ta.value = val;
            if (!isRestore) fire(ta, ['input', 'change']);
            else fireChange(ta);
            return true;
        }
        return false;
    }

    // =========================================================================
    //  DROPDOWN / AWESOMPLETE SUPPRESSION
    // =========================================================================

    function hideAwesomplete(wrapper) {
        if (!wrapper) return;
        wrapper.querySelectorAll(
            '.awesomplete > ul, ul[role="listbox"], .link-field-popup'
        ).forEach(function (ul) {
            ul.style.setProperty('display',    'none',   'important');
            ul.style.setProperty('visibility', 'hidden', 'important');
            ul.setAttribute('aria-hidden', 'true');
        });
        var aw = wrapper.querySelector('.awesomplete');
        if (aw) aw.classList.remove('open');
    }

    window._fle_killDropdownsGlobal = function () {
        document.querySelectorAll(
            '.dropdown-menu, .awesomplete > ul, ul.awesomplete, .link-field-popup'
        ).forEach(function (dd) {
            dd.style.display    = 'none';
            dd.style.visibility = 'hidden';
            dd.setAttribute('aria-hidden', 'true');
        });
        document.querySelectorAll('.awesomplete').forEach(function (aw) {
            aw.classList.remove('open');
        });
    };

    // =========================================================================
    //  VERIFY
    //  FIX 2d: Attach fields always pass — set_value is async so DOM verify
    //          would incorrectly fail and re-queue the field endlessly
    // =========================================================================

    function verifyField(cfg, expected) {
        if (cfg.type === 'check')  return true;
        if (cfg.type === 'attach') return true;   // FIX 2d
        var actual = readField(cfg);
        if (!actual) return false;
        return actual.toLowerCase() === expected.toLowerCase();
    }

    // =========================================================================
    //  SAVE DRAFT
    // =========================================================================

    function saveDraft(silent) {
        var fields    = discoverFields();
        var userEmail = getUserEmail();
        var draft = {
            __saved_at  : new Date().toLocaleString(),
            __user_email: userEmail,
            __fields    : []
        };

        fields.forEach(function (cfg) {
            var v = readField(cfg);
            draft[cfg.fieldname] = v;
            draft.__fields.push({ fieldname: cfg.fieldname, type: cfg.type });
            if (v) console.log('[Draft] Save:', cfg.fieldname, '(' + cfg.type + ') =', JSON.stringify(v));
        });

        fields.forEach(function (cfg) {
            if (cfg.type === 'check' && draft[cfg.fieldname] === '') draft[cfg.fieldname] = '0';
        });

        var ok = Store.save(draft);
        if (!silent) {
            showToast(
                ok ? '💾 Draft saved at ' + draft.__saved_at
                   : '❌ Could not save — storage unavailable',
                ok ? '#16a34a' : '#dc2626'
            );
        }
        console.log('[Draft] Saved ' + fields.length + ' fields (ok=' + ok + ')');
    }

    // =========================================================================
    //  AUTO-SAVE
    // =========================================================================

    var _autoTimer = null;
    function scheduleAutoSave() {
        clearTimeout(_autoTimer);
        _autoTimer = setTimeout(function () { saveDraft(true); }, 1500);
    }

    // =========================================================================
    //  RESTORE DRAFT
    //  FIX 2e: Attach fields are handled in their own branch — they skip the
    //          DOM-readiness checks that apply to select fields, and skip the
    //          verifyField loop (always pass). They wait for frappe.web_form.
    // =========================================================================

    function restoreDraft() {
        var draft = Store.load();
        if (!draft) return;

        var currentEmail = getUserEmail();
        if (currentEmail && draft.__user_email &&
            draft.__user_email.toLowerCase() !== currentEmail.toLowerCase()) {
            console.warn('[Draft] Draft belongs to', draft.__user_email,
                         '— current user is', currentEmail, '— skipping restore.');
            return;
        }

        var savedFields = (draft.__fields || []).slice();
        var seen = {};
        savedFields.forEach(function (f) { seen[f.fieldname] = true; });
        Object.keys(TYPED_FIELDS).forEach(function (fn) {
            if (!seen[fn] && draft[fn] !== undefined) {
                savedFields.push({ fieldname: fn, type: TYPED_FIELDS[fn] });
            }
        });

        var pending = savedFields.filter(function (cfg) {
            var v = draft[cfg.fieldname];
            if (cfg.type === 'check') return v === '1' || v === '0';
            return !!v;
        });

        if (!pending.length) return;

        console.log('[Draft] Restore pending:', pending.map(function (f) { return f.fieldname; }));

        var attempts = 0, MAX = 80, toastShown = false;

        function attempt() {
            attempts++;
            var still = [];

            pending.forEach(function (cfg) {

                // FIX 2e: Attach fields — wait for frappe.web_form, then restore
                if (cfg.type === 'attach') {
                    if (!window.frappe || !frappe.web_form) {
                        still.push(cfg);
                        return;
                    }
                    writeAttachField(cfg.fieldname, draft[cfg.fieldname]);
                    // verifyField always true for attach — do not re-queue
                    console.log('[Draft] ✅ Attach queued restore:', cfg.fieldname);
                    return;
                }

                var wrapper = document.querySelector('[data-fieldname="' + cfg.fieldname + '"]');
                if (!wrapper) { still.push(cfg); return; }

                if (cfg.type === 'select') {
                    var sel = wrapper.querySelector('select');
                    var inp = wrapper.querySelector('input.input-with-feedback');
                    if (!((sel && sel.options.length > 1) || inp)) {
                        still.push(cfg); return;
                    }
                }

                writeField(cfg, draft[cfg.fieldname], true);

                if (!verifyField(cfg, draft[cfg.fieldname])) {
                    still.push(cfg);
                } else {
                    console.log('[Draft] ✅ Restored:', cfg.fieldname, '->', draft[cfg.fieldname]);
                }
            });

            pending = still;

            if (pending.length === 0) {
                onDone(draft, toastShown); toastShown = true;
            } else if (attempts < MAX) {
                setTimeout(attempt, 100);
            } else {
                console.warn('[Draft] Timed out restoring:',
                    pending.map(function (f) { return f.fieldname; }));
                if (!toastShown) { onDone(draft, false); toastShown = true; }
            }
        }

        attempt();
    }

    function onDone(draft, alreadyShown) {
        setTimeout(updatePayBtn, 100);
        if (!alreadyShown && draft.__saved_at) {
            showToast('📋 Draft restored from ' + draft.__saved_at, '#2563eb');
        }
    }

    // =========================================================================
    //  PROCEED TO PAY — WRAPPER APPROACH
    // =========================================================================

    function getPayBtn() {
        var candidates = Array.prototype.slice.call(document.querySelectorAll(
            'button.submit-btn, button.btn-primary, button[data-action="submit"], ' +
            'button[type="submit"], .web-form-footer button, .page-actions button, ' +
            '.form-footer button'
        ));
        for (var i = 0; i < candidates.length; i++) {
            var txt = (candidates[i].textContent || '').toLowerCase().trim();
            if (txt.indexOf('pay')     !== -1 ||
                txt.indexOf('proceed') !== -1 ||
                txt.indexOf('submit')  !== -1) {
                return candidates[i];
            }
        }
        return document.querySelector(
            '.web-form-footer button.btn-primary, .page-actions button.btn-primary, ' +
            '.form-footer button.btn-primary, button.btn-primary.submit-btn'
        );
    }

    function getWrapper() {
        return document.getElementById('fle-pay-btn-wrapper');
    }

    function wrapPayBtn() {
        var btn = getPayBtn();
        if (!btn) return null;
        var existingWrapper = getWrapper();
        if (existingWrapper && existingWrapper.contains(btn)) return existingWrapper;
        var wrapper = document.createElement('span');
        wrapper.id  = 'fle-pay-btn-wrapper';
        wrapper.setAttribute('data-fle-state', 'visible');
        wrapper.style.cssText = 'display:inline-flex;align-items:center;';
        btn.parentNode.insertBefore(wrapper, btn);
        wrapper.appendChild(btn);
        console.log('[Pay] Button wrapped in #fle-pay-btn-wrapper');
        return wrapper;
    }

    function getFieldValue(fn) {
        var type = TYPED_FIELDS[fn] || 'text';
        var val  = readField({ fieldname: fn, type: type });
        if (val && val.trim()) return val.trim();
        try {
            if (window.frappe && frappe.web_form && frappe.web_form.doc) {
                var dv = frappe.web_form.doc[fn];
                if (dv && dv.toString().trim()) return dv.toString().trim();
            }
        } catch (e) { /* ignore */ }
        return '';
    }

    var _lastMissingLog = 0;

    function allFilled() {
        var missing = [];
        REQUIRED_FOR_PAY.forEach(function (fn) {
            if (!getFieldValue(fn)) missing.push(fn);
        });
        if (missing.length) {
            var now = Date.now();
            if (now - _lastMissingLog > 2000) {
                console.log('[Pay] Missing:', missing);
                _lastMissingLog = now;
            }
        }
        return missing.length === 0;
    }

    function updatePayBtn() {
        var wrapper = wrapPayBtn();
        if (!wrapper) return;
        wrapper.setAttribute('data-fle-state', 'visible');
    }

    function ensurePayBtnWrapped() {
        var wrapper = wrapPayBtn();
        if (wrapper && !wrapper.__fle_click_guard) {
            wrapper.__fle_click_guard = true;
            attachPayBtnClickGuard(wrapper);
        }
    }

    // =========================================================================
    //  PAY BUTTON CLICK GUARD — show alert when mandatory fields are missing
    // =========================================================================

    var FIELD_LABELS = {
        'email_address'           : 'Email Address',
        'candidate_name'          : 'Name (as it should appear on the certificate)',
        'candidate_dob'           : 'Date of Birth',
        'candidate_gender'        : 'Gender',
        'candidate_contact_number': 'Contact Number',
        'country_of_residence'    : 'Country of Residence',
        'city'                    : 'City',
        'candidates_state'        : 'State',
        'where_did_you_hear'           : 'How did you hear about the FLE programme?',
        'candidate_current_occupation' : 'What are you doing currently?',
        'last_class_attended'          : 'Last Examination Attended',
        'latest_board_attended'   : 'Latest Board Attended',
        'year_of_passing'         : 'Year of Passing',
        'id_card_scan'            : 'Government Approved ID Card (upload)',
        'candidate_photo'         : "Candidate's Photo (upload)",
        'declaration_consent'     : 'Declaration Consent (checkbox)'
    };

    function getMissingFields() {
        var missing = [];
        REQUIRED_FOR_PAY.forEach(function (fn) {
            if (!getFieldValue(fn)) missing.push(FIELD_LABELS[fn] || fn);
        });
        return missing;
    }

    function showMissingFieldsAlert(missing) {
        $('#fle-missing-alert').remove();
        var listHtml = missing.map(function (f) {
            return '<li style="margin:4px 0;padding:0;">' + f + '</li>';
        }).join('');
        var html = '<div id="fle-missing-alert" style="' +
            'position:fixed;top:0;left:0;width:100%;height:100%;' +
            'background:rgba(0,0,0,0.5);z-index:999999;' +
            'display:flex;align-items:center;justify-content:center;">' +
            '<div style="background:#fff;border-radius:10px;padding:36px 40px 32px;' +
            'max-width:460px;width:90%;font-family:Merriweather,Georgia,serif;' +
            'box-shadow:0 20px 60px rgba(0,0,0,0.25);text-align:left;">' +
            '<div style="display:flex;align-items:center;gap:12px;margin-bottom:16px;">' +
            '<span style="font-size:28px;">⚠️</span>' +
            '<h3 style="margin:0;font-size:17px;font-weight:700;color:#8B0000;font-family:inherit;">' +
            'Please fill all required fields</h3></div>' +
            '<p style="margin:0 0 12px;font-size:13px;color:#444;font-weight:300;line-height:1.6;font-family:inherit;">' +
            'The following mandatory fields must be completed before proceeding to payment:</p>' +
            '<ul style="margin:0 0 24px 18px;padding:0;font-size:13px;color:#1a1a1a;' +
            'font-weight:600;line-height:1.8;font-family:inherit;">' + listHtml + '</ul>' +
            '<div style="text-align:right;">' +
            '<button id="fle-missing-ok" type="button" style="' +
            'display:inline-flex !important;align-items:center !important;' +
            'justify-content:center !important;background-color:#8B0000 !important;' +
            'color:#ffffff !important;padding:10px 28px !important;' +
            'border:none !important;border-radius:5px !important;' +
            'font-family:Merriweather,Georgia,serif !important;font-size:13px !important;' +
            'font-weight:700 !important;cursor:pointer !important;letter-spacing:0.5px !important;' +
            'box-shadow:0 2px 6px rgba(139,0,0,0.35) !important;' +
            'text-decoration:none !important;white-space:nowrap !important;">' +
            'OK, Got It</button></div></div></div>';
        $('body').append(html);
        $('#fle-missing-ok, #fle-missing-alert').on('click', function (e) {
            if (e.target.id === 'fle-missing-ok' || e.target.id === 'fle-missing-alert') {
                $('#fle-missing-alert').remove();
            }
        });
    }

    function attachPayBtnClickGuard(wrapper) {
        var btn = wrapper.querySelector('button');
        if (!btn || btn.__fle_guard) return;
        btn.__fle_guard = true;
        btn.addEventListener('click', function (e) {
            var missing = getMissingFields();
            if (missing.length > 0) {
                e.preventDefault();
                e.stopImmediatePropagation();
                showMissingFieldsAlert(missing);
            } else {
                // All fields filled — save draft silently before navigating to payment.
                // This ensures data is preserved if payment is cancelled or fails.
                try { saveDraft(true); } catch (ex) { /* ignore */ }
            }
        }, true); // capture phase so it fires before Frappe's handlers
    }

    var _payObserver = new MutationObserver(function (mutations) {
        var hasNew = mutations.some(function (m) { return m.addedNodes.length > 0; });
        if (!hasNew) return;
        ensurePayBtnWrapped();
        updatePayBtn();
    });
    _payObserver.observe(document.body || document.documentElement, {
        childList: true,
        subtree  : true
    });

    var _rafBoot = true;
    (function rafBootLoop() {
        if (!_rafBoot) return;
        ensurePayBtnWrapped();
        updatePayBtn();
        requestAnimationFrame(rafBootLoop);
    })();
    setTimeout(function () { _rafBoot = false; }, 2000);

    // =========================================================================
    //  FIX 3: HIDE DISCARD BUTTON
    //  Collapses any footer button whose visible text is "discard".
    //  Called every 300 ms interval and at boot so it catches dynamically
    //  rendered footers. applyFooterButtonStyles() skips it so it is never
    //  accidentally made visible again.
    // =========================================================================

    function hideDiscardButton() {
        document.querySelectorAll(
            '.web-form-footer button, .page-actions button, .form-footer button'
        ).forEach(function (btn) {
            if (btn.id === 'fle-save-draft-btn') return;
            var label = (btn.textContent || btn.innerText || '').trim().toLowerCase();
            if (label !== 'discard') return;
            btn.id = 'fle-discard-hidden';   // CSS rule above finishes the job
            btn.style.setProperty('display',        'none',   'important');
            btn.style.setProperty('visibility',     'hidden', 'important');
            btn.style.setProperty('pointer-events', 'none',   'important');
            btn.style.setProperty('width',          '0',      'important');
            btn.style.setProperty('height',         '0',      'important');
            btn.style.setProperty('margin',         '0',      'important');
            btn.style.setProperty('padding',        '0',      'important');
            btn.style.setProperty('overflow',       'hidden', 'important');
            btn.setAttribute('aria-hidden', 'true');
            console.log('[FLE] Discard button hidden.');
        });
    }

    // =========================================================================
    //  APPLY FOOTER BUTTON STYLES
    //  FIX 3: Skip the Discard button so it is never re-styled as visible
    // =========================================================================

    function applyFooterButtonStyles() {
        var footerBtns = document.querySelectorAll(
            '.web-form-footer .btn, .web-form-footer button, ' +
            '.page-actions .btn,   .page-actions button, ' +
            '.form-footer .btn,    .form-footer button'
        );

        footerBtns.forEach(function (btn) {
            if (btn.id === 'fle-logout-btn' || btn.classList.contains('fle-logout-btn')) return;

            var label = (btn.textContent || btn.innerText || '').trim().toLowerCase();

            // FIX 3: never re-style the Discard button — keep it hidden
            if (label === 'discard' || btn.id === 'fle-discard-hidden') {
                hideDiscardButton();
                return;
            }

            var cls = (btn.className || '').toString();

            var isPayBtn    = cls.indexOf('btn-primary') !== -1 ||
                              cls.indexOf('submit-btn')  !== -1 ||
                              label.indexOf('proceed')   !== -1 ||
                              label.indexOf('pay')       !== -1 ||
                              label.indexOf('submit')    !== -1;
            var isDangerBtn = cls.indexOf('btn-danger')  !== -1 || label === 'delete';

            btn.style.setProperty('box-sizing',      'border-box',                                                     'important');
            btn.style.setProperty('display',         'inline-flex',                                                    'important');
            btn.style.setProperty('align-items',     'center',                                                         'important');
            btn.style.setProperty('justify-content', 'center',                                                         'important');
            btn.style.setProperty('white-space',     'nowrap',                                                         'important');
            btn.style.setProperty('font-family',     "'Merriweather', Georgia, serif",                                 'important');
            btn.style.setProperty('font-size',       '13px',                                                           'important');
            btn.style.setProperty('font-weight',     '700',                                                            'important');
            btn.style.setProperty('letter-spacing',  '0.5px',                                                         'important');
            btn.style.setProperty('padding',         '10px 28px',                                                      'important');
            btn.style.setProperty('border-radius',   '5px',                                                           'important');
            btn.style.setProperty('cursor',          'pointer',                                                        'important');
            btn.style.setProperty('min-height',      '40px',                                                          'important');
            btn.style.setProperty('line-height',     '1',                                                             'important');
            btn.style.setProperty('text-decoration', 'none',                                                          'important');
            btn.style.setProperty('text-transform',  'none',                                                          'important');
            btn.style.setProperty('margin',          '0 8px',                                                         'important');
            btn.style.setProperty('transition',      'background-color 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease', 'important');

            if (isPayBtn) {
                btn.style.setProperty('background-color', '#8B0000',                       'important');
                btn.style.setProperty('color',            '#ffffff',                       'important');
                btn.style.setProperty('border',           '2px solid #8B0000',             'important');
                btn.style.setProperty('box-shadow',       '0 2px 6px rgba(139,0,0,0.35)', 'important');
            } else if (isDangerBtn) {
                btn.style.setProperty('background-color', '#ffffff',           'important');
                btn.style.setProperty('color',            '#cc0000',           'important');
                btn.style.setProperty('border',           '2px solid #cc0000', 'important');
                btn.style.setProperty('box-shadow',       'none',              'important');
            } else {
                btn.style.setProperty('background-color', '#ffffff',           'important');
                btn.style.setProperty('color',            '#8B0000',           'important');
                btn.style.setProperty('border',           '2px solid #8B0000', 'important');
                btn.style.setProperty('box-shadow',       'none',              'important');
            }
        });

        var payWrapper = document.getElementById('fle-pay-btn-wrapper');
        if (payWrapper) {
            payWrapper.style.setProperty('display',     'inline-flex', 'important');
            payWrapper.style.setProperty('align-items', 'center',      'important');
            payWrapper.style.setProperty('margin',      '0 8px',       'important');
            payWrapper.style.setProperty('padding',     '0',           'important');
        }

        document.querySelectorAll('.web-form-footer, .page-actions, .form-footer')
            .forEach(function (footer) {
