    // =========================================================================
    //  CHECKBOX ALIGNMENT — DOM RECONSTRUCTION
    // =========================================================================

    function fixCheckboxAlignment() {
        var FIELD   = 'i_hereby_consent_to_this_declaration';
        var wrapper = document.querySelector('[data-fieldname="' + FIELD + '"]');
        if (!wrapper) return;

        var chk = wrapper.querySelector('input[type="checkbox"]');
        if (!chk) return;

        if (wrapper.__chk_rebuilt && document.contains(wrapper.__chk_rebuilt)) return;

        var labelText = '';
        var labelEl   = null;

        var parentLabel = chk.closest('label');
        if (parentLabel) {
            var labelClone = parentLabel.cloneNode(true);
            var cloneChk   = labelClone.querySelector('input[type="checkbox"]');
            if (cloneChk) cloneChk.parentNode.removeChild(cloneChk);
            labelText = labelClone.textContent.trim();
            labelEl   = parentLabel;
        }

        if (!labelText) {
            var searchRoot = chk.parentNode || wrapper;
            var allEls = Array.prototype.slice.call(
                searchRoot.querySelectorAll('label, .label-area, .static-area, span, div')
            );
            for (var i = 0; i < allEls.length; i++) {
                var el  = allEls[i];
                var txt = el.textContent.trim();
                if (txt && (txt.toLowerCase().indexOf('consent')     !== -1 ||
                            txt.toLowerCase().indexOf('declaration') !== -1)) {
                    labelText = txt;
                    labelEl   = el;
                    break;
                }
            }
        }

        if (!labelText) {
            var chkParent = chk.parentNode;
            var siblings  = chkParent ? Array.prototype.slice.call(chkParent.childNodes) : [];
            for (var j = 0; j < siblings.length; j++) {
                var sib = siblings[j];
                if (sib === chk) continue;
                var sibText = (sib.textContent || '').trim();
                if (sibText) { labelText = sibText; labelEl = sib; break; }
            }
        }

        var row       = document.createElement('label');
        row.className = 'fle-check-row';
        row.htmlFor   = chk.id || '';

        var chkParentNode = chk.parentNode;
        row.appendChild(chk);

        var textSpan         = document.createElement('span');
        textSpan.className   = 'fle-check-label';
        textSpan.textContent = labelText || 'I Hereby Consent To This Declaration.';
        row.appendChild(textSpan);

        if (labelEl && labelEl !== chk) {
            labelEl.classList.add('fle-chk-original-hidden');
            labelEl.style.setProperty('display', 'none', 'important');
        }

        if (chkParentNode && chkParentNode !== wrapper &&
            chkParentNode.textContent.trim() === '' &&
            !chkParentNode.querySelector('input, select, textarea')) {
            chkParentNode.style.setProperty('display', 'none', 'important');
        }

        if (wrapper.firstChild) {
            wrapper.insertBefore(row, wrapper.firstChild);
        } else {
            wrapper.appendChild(row);
        }

        wrapper.__chk_rebuilt = row;

        row.addEventListener('click', function () {
            fire(chk, ['change']);
            scheduleAutoSave();
        });

        console.log('[FLE] ✅ Checkbox reconstructed. Label: "' + labelText + '"');
    }

