                // Always use session user as email fallback (works on refresh too)
                var email = data.email || (
                    frappe.session && frappe.session.user && frappe.session.user !== 'Guest'
                        ? frappe.session.user : ''
                );
                var mobile = data.mobile || '';
                var attempts = 0;
                function trySet() {
                    if (!window.frappe || !frappe.web_form) {
                        if (attempts++ < 30) setTimeout(trySet, 300);
                        return;
                    }
                    if (email) {
                        frappe.web_form.set_value('email_address', email);
                        var ef = frappe.web_form.fields_dict && frappe.web_form.fields_dict['email_address'];
                        if (ef) { ef.df.read_only = 1; ef.refresh(); }
                    }
