    // =========================================================================
    //  RETRY PAYMENT — show Proceed to Pay for existing unpaid documents
    //  (Frappe only renders the payment button for new docs; on refresh the
    //  existing doc is loaded and the button disappears — this restores it.)
    // =========================================================================

    (function retryPaymentOnLoad() {

        function doPayment(docname, btn) {
            btn.disabled    = true;
            btn.textContent = 'Processing...';

            // Build doc data and ensure phone includes country code (intlTelInput
            // shows "+91" in the UI but stores only the local number in doc)
            var docData = JSON.parse(JSON.stringify(frappe.web_form.doc));
            try {
                var pf = frappe.web_form.fields_dict &&
                         frappe.web_form.fields_dict['candidate_contact_number'];
                if (pf && pf.$input) {
                    var inp = pf.$input.get(0);
                    if (window.intlTelInput && intlTelInput.getInstance) {
                        var iti = intlTelInput.getInstance(inp);
                        if (iti) {
                            var full = iti.getNumber(); // e.g. "+918756565656"
                            if (full) docData.candidate_contact_number = full;
                        }
                    }
                }
            } catch (e) { /* ignore — use raw doc value */ }

            frappe.call({
                method: 'frappe.website.doctype.web_form.web_form.accept',
                args: {
                    web_form   : 'foundations-for-a-legal-education',
                    data       : JSON.stringify(docData),
                    docname    : docname,
                    for_payment: true
                },
                callback: function (r) {
                    if (r.message && typeof r.message === 'string' &&
                        r.message.indexOf('http') === 0) {
                        window.location.href = r.message;
                    } else {
                        btn.disabled    = false;
                        btn.textContent = 'Proceed to Pay';
                    }
                }
            });
        }

        function tryShowPayBtn(attempts) {
            attempts = attempts || 0;
            if (!window.frappe || !frappe.web_form || !frappe.web_form.doc) {
                if (attempts < 40) setTimeout(function () { tryShowPayBtn(attempts + 1); }, 300);
                return;
            }

            var docname = frappe.web_form.doc.name;
            if (!docname) return; // New document — Frappe handles it natively

            frappe.call({
                method: 'slcm.api.user.get_payment_status',
                args: { docname: docname },
                callback: function (r) {
                    var data = (r && r.message) || {};
                    if (data.payment_status === 'Paid') return; // Already paid

                    setTimeout(function () {
                        var footer = document.querySelector(
                            '.web-form-footer, .page-actions, .form-footer'
                        );
                        if (!footer) return;

                        // If Frappe already rendered a Proceed to Pay button, hijack it
                        var existingBtn = null;
                        footer.querySelectorAll('button').forEach(function (b) {
                            if (b.id === 'fle-save-draft-btn' || b.id === 'fle-retry-pay-btn') return;
                            var txt = (b.textContent || '').trim().toLowerCase();
                            if (txt.indexOf('pay') !== -1 || txt.indexOf('proceed') !== -1) {
                                existingBtn = b;
                            }
                        });

                        if (existingBtn) {
                            // Hijack: replace all click handlers with our payment call
                            var fresh = existingBtn.cloneNode(true);
                            existingBtn.parentNode.replaceChild(fresh, existingBtn);
                            fresh.addEventListener('click', function (e) {
                                e.preventDefault();
                                e.stopImmediatePropagation();
                                doPayment(docname, fresh);
                            }, true);
                            return;
                        }

                        // No button found — hide Update/Save and inject our own
                        if (document.getElementById('fle-retry-pay-btn')) return;
                        footer.querySelectorAll('button').forEach(function (b) {
                            if (b.id === 'fle-save-draft-btn') return;
                            var txt = (b.textContent || '').trim().toLowerCase();
                            if (txt === 'update' || txt === 'save') {
                                b.style.setProperty('display', 'none', 'important');
                            }
                        });

                        var btn = document.createElement('button');
                        btn.id          = 'fle-retry-pay-btn';
                        btn.type        = 'button';
                        btn.className   = 'btn btn-primary';
                        btn.textContent = 'Proceed to Pay';
                        btn.addEventListener('click', function () { doPayment(docname, btn); });
                        footer.appendChild(btn);
                    }, 1200);
                }
            });
        }

        tryShowPayBtn();
    })();



