    // ── 2. Patch FileUploader prototype — force is_private = 0 ──────────────
    (function patchFileUploader() {
        function tryPatch() {
            if (!window.frappe || !frappe.ui || !frappe.ui.FileUploader) return false;
            var proto = frappe.ui.FileUploader.prototype;
            if (proto.upload_files && proto.upload_files.__fle_patched) return true;

            var origUpload = proto.upload_files;
            proto.upload_files = function () {
                (this.files || []).forEach(function (f) {
                    f.is_private = 0;
                    f.private    = 0;
                });
                return origUpload.call(this);
            };
            proto.upload_files.__fle_patched = true;

            if (proto.make_upload_request && !proto.make_upload_request.__fle_patched) {
                var origReq = proto.make_upload_request;
                proto.make_upload_request = function (file) {
                    return origReq.call(this, file, 0);
                };
                proto.make_upload_request.__fle_patched = true;
            }

            if (proto.upload_via_web_link && !proto.upload_via_web_link.__fle_patched) {
                var origLink = proto.upload_via_web_link;
                proto.upload_via_web_link = function (fileurl) {
                    if (this.upload_options) this.upload_options.is_private = 0;
                    return origLink.call(this, fileurl);
                };
                proto.upload_via_web_link.__fle_patched = true;
            }

            console.log('[FLE] FileUploader patched.');
            return true;
        }
        if (!tryPatch()) {
            var t = setInterval(function () { if (tryPatch()) clearInterval(t); }, 300);
        }
    })();

    // Patch frappe.upload
    (function patchFrappeUpload() {
        function tryPatch() {
            if (!window.frappe || !frappe.upload || frappe.upload.__fle_patched) return false;
            var orig = frappe.upload;
            frappe.upload = function (options) {
                if (options) options.is_private = 0;
                return orig(options);
            };
            frappe.upload.__fle_patched = true;
            return true;
        }
        if (!tryPatch()) {
            var t = setInterval(function () { if (tryPatch()) clearInterval(t); }, 300);
        }
    })();

