    // ── 4. Core hide function ────────────────────────────────────────────────
    function hideUploadExtras() {
        var root = document.body;

        root.querySelectorAll('input[type="checkbox"]').forEach(function (chk) {
            var container = chk.closest('label') || chk.parentElement;
            if (!container) return;
            var txt = container.textContent.trim().toLowerCase();
            if (txt.indexOf('private')     !== -1 &&
                txt.indexOf('consent')     === -1 &&
                txt.indexOf('declaration') === -1 &&
                txt.indexOf('hereby')      === -1 &&
                txt.indexOf('authoris')    === -1 &&
                txt.indexOf('pledge')      === -1) {
                if (chk.checked) {
                    chk.checked = false;
                    chk.dispatchEvent(new Event('change', { bubbles: true }));
                }
                if (container.style.display !== 'none') {
                    container.style.setProperty('display', 'none', 'important');
                    console.log('[FLE] Hidden: Private checkbox row');
                }
            }
        });

        root.querySelectorAll('button').forEach(function (btn) {
            var t = btn.textContent.trim().toLowerCase();
            if (t === 'set all private' || t === 'set all public') {
                btn.style.setProperty('display', 'none', 'important');
            }
        });

        root.querySelectorAll('p, div, span, section').forEach(function (el) {
            if (el.children.length > 5) return;
            var txt = el.textContent.trim().toLowerCase();
            if ((txt.indexOf('file is public')     !== -1 ||
                 txt.indexOf('accessed by anyone') !== -1 ||
                 txt.indexOf('without logging in') !== -1) &&
                txt.length < 500) {
                var banner = el.closest('[class*="warn"]')   ||
                             el.closest('[class*="alert"]')  ||
                             el.closest('[class*="notice"]') ||
                             el.closest('[class*="info"]')   ||
                             el.parentElement;
                if (banner && banner.style.display !== 'none') {
                    banner.style.setProperty('display', 'none', 'important');
                }
                if (el.style.display !== 'none') {
                    el.style.setProperty('display', 'none', 'important');
                }
            }
        });

        ['Link', 'Camera'].forEach(function (label) {
            root.querySelectorAll('p, span, div').forEach(function (el) {
                if (el.textContent.trim() !== label) return;
                var tile = el;
                for (var i = 0; i < 6; i++) {
                    var parent = tile.parentElement;
                    if (!parent) break;
                    var hasSiblingWithDevice = Array.prototype.slice
                        .call(parent.children)
                        .some(function (s) {
                            return s !== tile &&
                                   s.textContent.trim().toLowerCase().indexOf('device') !== -1;
                        });
                    if (hasSiblingWithDevice) {
                        tile.style.setProperty('display', 'none', 'important');
                        break;
                    }
                    tile = parent;
                }
            });
        });
    }

    // ── 5. MutationObserver ──────────────────────────────────────────────────
    var _fle_rafPending = false;

    function scheduleHide() {
        if (_fle_rafPending) return;
        _fle_rafPending = true;
        requestAnimationFrame(function () {
            _fle_rafPending = false;
            hideUploadExtras();
        });
    }

    var _fle_observer = new MutationObserver(function (mutations) {
        var hasNewNodes = mutations.some(function (m) {
            return m.type === 'childList' && m.addedNodes.length > 0;
        });
        if (hasNewNodes) scheduleHide();
    });

    function connectObserver() {
        _fle_observer.disconnect();
        _fle_observer.observe(document.body, {
            childList  : true,
            subtree    : true,
            attributes : false
        });
        console.log('[FLE] Observer connected.');
    }

    function disconnectObserver() {
        _fle_observer.disconnect();
        _fle_rafPending = false;
    }

