        setTimeout(hideUploadExtras, 300);
        setTimeout(hideUploadExtras, 600);
        setTimeout(hideUploadExtras, 1000);
        setTimeout(hideUploadExtras, 1500);
    });

    // ── 8. CUSTOM UPLOAD UI — My Device only + auto field detection ──────────
    setTimeout(function () {

        function customizeUploader() {
            var uploadArea = document.querySelector('.file-upload-area');
            if (!uploadArea || uploadArea.classList.contains('customized')) return;

            uploadArea.classList.add('customized');
            uploadArea.innerHTML = [
                '<div style="text-align:center;padding:30px 20px">',
                '  <div style="margin-bottom:20px">',
                '    <svg width="64" height="64" viewBox="0 0 24 24" fill="none" stroke="#888" stroke-width="2">',
                '      <rect x="3" y="3" width="18" height="18" rx="2" ry="2"/>',
                '      <circle cx="8.5" cy="8.5" r="1.5"/>',
                '      <polyline points="21 15 16 10 5 21"/>',
                '    </svg>',
                '  </div>',
                '  <div style="color:#666;font-size:15px;margin-bottom:20px">',
                '    Drag and drop files here or upload from',
                '  </div>',
                '  <button class="btn btn-default btn-my-device" type="button" style="padding:8px 20px">',
                '    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor"',
                '         stroke-width="2" style="margin-right:6px;vertical-align:middle">',
                '      <rect x="2" y="3" width="20" height="14" rx="2" ry="2"/>',
                '      <line x1="8" y1="21" x2="16" y2="21"/>',
                '      <line x1="12" y1="17" x2="12" y2="21"/>',
                '    </svg>',
                '    My Device',
                '  </button>',
                '</div>'
            ].join('');

            var fileInput           = document.createElement('input');
            fileInput.type          = 'file';
            fileInput.style.display = 'none';
            fileInput.className     = 'custom-file-input';
            fileInput.setAttribute(
                'accept',
                '.pdf,.doc,.docx,.jpg,.jpeg,.png,' +
                'application/pdf,application/msword,' +
                'application/vnd.openxmlformats-officedocument.wordprocessingml.document,' +
                'image/jpeg,image/png'
            );
            uploadArea.appendChild(fileInput);

            var myDeviceBtn = uploadArea.querySelector('.btn-my-device');
            if (myDeviceBtn) {
                myDeviceBtn.addEventListener('click', function (e) {
                    e.preventDefault();
                    e.stopPropagation();
                    fileInput.click();
                });
            }

            uploadArea.addEventListener('dragover', function (e) {
                e.preventDefault();
                e.stopPropagation();
                uploadArea.style.backgroundColor = '#f0f8ff';
                uploadArea.style.borderColor     = '#4a90e2';
            });
            uploadArea.addEventListener('dragleave', function (e) {
                e.preventDefault();
                e.stopPropagation();
                uploadArea.style.backgroundColor = '';
                uploadArea.style.borderColor     = '';
            });
            uploadArea.addEventListener('drop', function (e) {
                e.preventDefault();
                e.stopPropagation();
                uploadArea.style.backgroundColor = '';
                uploadArea.style.borderColor     = '';
                if (e.dataTransfer.files.length > 0) handleFileSelect(e.dataTransfer.files[0]);
            });

            fileInput.addEventListener('change', function (e) {
                if (e.target.files.length > 0) handleFileSelect(e.target.files[0]);
            });

            function handleFileSelect(file) {
                var allowedTypes = [
                    'application/pdf',
                    'application/msword',
                    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
                    'image/jpeg',
                    'image/png',
                    'image/jpg'
                ];
                var ext         = file.name.split('.').pop().toLowerCase();
                var allowedExts = ['pdf', 'doc', 'docx', 'jpg', 'jpeg', 'png'];
                if (!allowedTypes.includes(file.type) && !allowedExts.includes(ext)) {
                    frappe.msgprint({
                        title    : 'Invalid File Type',
                        message  : '❌ Please upload a PDF, Word document, or image file.',
                        indicator: 'red'
                    });
                    return;
                }
                uploadFileToFrappe(file);
            }

            function uploadFileToFrappe(file) {
                var formData = new FormData();
                formData.append('file',      file);
                formData.append('is_private', '0');
                formData.append('folder',    'Home');
                formData.append('file_name', file.name);

                frappe.show_alert({ message: __('Uploading...'), indicator: 'blue' }, 3);

                fetch('/api/method/upload_file', {
                    method : 'POST',
                    headers: { 'X-Frappe-CSRF-Token': frappe.csrf_token },
                    body   : formData
                })
                .then(function (response) { return response.json(); })
                .then(function (data) {
                    if (data.message && data.message.file_url) {
                        var fileUrl     = data.message.file_url;
                        var targetField = _fle_activeFieldname;

                        // Fallback: find first empty Attach field
                        if (!targetField && frappe.web_form) {
                            var fields = frappe.web_form.fields_dict || {};
                            Object.keys(fields).forEach(function (key) {
                                var field = fields[key];
                                if (field && field.df &&
                                    (field.df.fieldtype === 'Attach' ||
                                     field.df.fieldtype === 'Attach Image') &&
                                    !frappe.web_form.get_value(key)) {
                                    targetField = key;
                                }
                            });
                        }

                        console.log('[FLE] Setting field:', targetField, '=', fileUrl);

                        if (targetField && frappe.web_form) {
                            var origAfterSave   = frappe.web_form.after_save;
                            var origGoToSuccess = frappe.web_form.go_to_success_page;
                            frappe.web_form.after_save         = function () {};
                            frappe.web_form.go_to_success_page = function () {};

                            frappe.web_form.set_value(targetField, fileUrl);

                            setTimeout(function () {
                                var fieldEl = document.querySelector(
                                    '[data-fieldname="' + targetField + '"] input'
                                );
                                if (fieldEl) {
                                    fieldEl.value = fileUrl;
                                    fieldEl.dispatchEvent(new Event('change', { bubbles: true }));
                                }
                                if (frappe.web_form.fields_dict &&
                                    frappe.web_form.fields_dict[targetField]) {
                                    frappe.web_form.fields_dict[targetField].set_value(fileUrl);
                                    frappe.web_form.refresh_field(targetField);
                                }
                                // FIX 2f: persist attach URL to draft immediately after upload
                                scheduleAutoSave();
                            }, 200);

                            setTimeout(function () {
                                frappe.web_form.after_save         = origAfterSave;
                                frappe.web_form.go_to_success_page = origGoToSuccess;
                            }, 800);

                        } else {
                            console.warn('[FLE] Could not detect target field — file uploaded but not attached.');
                            frappe.msgprint({
                                title    : 'Attachment Warning',
                                message  : '⚠️ File uploaded but could not be attached automatically. Please refresh.',
                                indicator: 'orange'
                            });
                        }

                        // Close the modal
                        setTimeout(function () {
                            var closeBtn = document.querySelector(
                                '.modal.show .close, ' +
                                '.modal.show [data-dismiss="modal"], ' +
                                '.frappe-dialog .btn-modal-close'
                            );
                            if (closeBtn) closeBtn.click();
                        }, 400);

                        frappe.show_alert({ message: __('✓ File uploaded'), indicator: 'green' }, 3);

                    } else {
                        throw new Error('Invalid response');
                    }
                })
                .catch(function (error) {
                    console.error('[FLE] Upload error:', error);
                    frappe.msgprint({
                        title    : 'Upload Failed',
                        message  : '❌ Failed to upload file. Please try again.',
                        indicator: 'red'
                    });
                });
            }

            // Hide stray dialog buttons
            setTimeout(function () {
                document.querySelectorAll('button').forEach(function (btn) {
                    var txt = btn.textContent.toLowerCase().trim();
                    if (txt === 'set all private' || txt === 'set all public' || txt === 'upload') {
                        btn.style.setProperty('display', 'none', 'important');
                    }
                });
            }, 50);
        }

        [0, 50, 100, 200, 300, 500, 1000].forEach(function (delay) {
            setTimeout(customizeUploader, delay);
        });

        var uploadObserver = new MutationObserver(function (mutations) {
            mutations.forEach(function (mutation) {
                mutation.addedNodes.forEach(function (node) {
                    if (node.nodeType !== 1) return;
                    if ((node.classList &&
                         (node.classList.contains('file-uploader') ||
                          node.classList.contains('modal'))) ||
                        (node.querySelector && node.querySelector('.file-uploader'))) {
                        setTimeout(customizeUploader, 10);
                        setTimeout(customizeUploader, 100);
                    }
                });
            });
        });
        uploadObserver.observe(document.body, { childList: true, subtree: true });

        $(document).on(
            'click',
            '.attach-file-button, .btn-attach, [data-fieldname] .control-value',
            function () {
                [10, 50, 100, 200, 500].forEach(function (delay) {
                    setTimeout(customizeUploader, delay);
                });
            }
        );

    }, 100);

    // ── Boot ─────────────────────────────────────────────────────────────────
    hideUploadExtras();
    console.log('[FLE] Upload v11 — auto field detection — loaded.');

    // =========================================================================
    //  PHONE VALIDATION (Country-Aware v2 — Enforce-First)
    // =========================================================================

    (function initPhoneValidation() {
        var PHONE_FIELDS = [
            'candidate_contact_number',
            'parent_contact_number'
        ];

        function getDialCode(wrapper) {
            if (!wrapper) return '';
            try {
                var inputs = wrapper.querySelectorAll('input');
                for (var i = 0; i < inputs.length; i++) {
                    var inp = inputs[i];
                    var keys = Object.keys(inp);
                    for (var k = 0; k < keys.length; k++) {
                        var key = keys[k];
                        if ((key.indexOf('iti') !== -1 || key.indexOf('intl') !== -1) &&
                            inp[key] && typeof inp[key].getSelectedCountryData === 'function') {
                            var data = inp[key].getSelectedCountryData();
                            if (data && data.dialCode) return '+' + data.dialCode;
                        }
                    }
                    if (window.intlTelInputGlobals) {
                        var instance = intlTelInputGlobals.getInstance(inp);
                        if (instance) {
                            var d = instance.getSelectedCountryData();
                            if (d && d.dialCode) return '+' + d.dialCode;
                        }
                    }
                }
            } catch (e) {}
            var spans = wrapper.querySelectorAll(
                '.selected-dial-code, .iti__selected-dial-code, ' +
                '[class*="dial-code"], [class*="dialCode"]'
            );
            for (var s = 0; s < spans.length; s++) {
                var txt = (spans[s].textContent || '').trim();
                if (txt.match(/^\+\d+$/)) return txt;
            }
            var flag = wrapper.querySelector(
                '.iti_flag, [class*="iti_flag"], .selected-flag [class*="flag"]'
            );
            if (flag) {
                var cls = (flag.className || '').toLowerCase();
                var match = cls.match(/iti__([a-z]{2})\b/);
                if (match) {
                    var countryCode = match[1];
                    if (countryCode === 'in') return '+91';
                    var MAP = {
                        'us':'1','gb':'44','au':'61','ca':'1','de':'49',
                        'fr':'33','jp':'81','cn':'86','sg':'65','ae':'971'
                    };
                    if (MAP[countryCode]) return '+' + MAP[countryCode];
                }
            }
            try {
                var fn  = wrapper.getAttribute('data-fieldname');
                var doc = window.frappe && frappe.web_form && frappe.web_form.doc;
                if (doc && doc[fn]) {
                    var m = doc[fn].toString().match(/^(\+\d{1,4})/);
                    if (m) return m[1];
                }
            } catch (e) {}
            return '+91'; // default to India when no flag/code detected
        }

        function getMaxDigits(wrapper) {
            var code = getDialCode(wrapper);
            console.log('[FLE Phone] Dial code detected:', code,
                        'for field:', wrapper && wrapper.getAttribute('data-fieldname'));
            return (code === '+91') ? 10 : 15;
        }

        function enforceMax(input) {
            var wrapper = input.closest
                ? input.closest('[data-fieldname]')
                : (function () {
                    var el = input.parentNode;
                    while (el) {
                        if (el.getAttribute && el.getAttribute('data-fieldname')) return el;
                        el = el.parentNode;
                    }
                    return null;
                })();
            var max    = wrapper ? getMaxDigits(wrapper) : 15;
            var raw    = input.value.replace(/\D/g, '');
            var capped = raw.slice(0, max);
            if (input.value !== capped) {
                var pos = input.selectionStart || 0;
                input.value = capped;
                try {
                    var newPos = Math.min(pos, capped.length);
                    input.setSelectionRange(newPos, newPos);
                } catch (e) {}
                if (raw.length > max) {
                    showLimitAlert(max, wrapper && wrapper.getAttribute('data-fieldname'));
                }
            }
            return { max: max, value: capped };
        }

        var _alertDebounce = {};
        function showLimitAlert(max, fieldname) {
            var key = fieldname || 'default';
            if (_alertDebounce[key]) return;
            _alertDebounce[key] = true;
            setTimeout(function () { delete _alertDebounce[key]; }, 2500);
            frappe.show_alert({
                message  : '⚠️ Max ' + max + ' digits allowed' +
                           (max === 10 ? ' for India (+91)' : ''),
                indicator: 'orange'
            }, 3);
        }

        function applyValidation(input) {
            if (!input || input.__fle_phone_v2) return;
            input.__fle_phone_v2 = true;

            input.addEventListener('input', function () {
                enforceMax(this);
                if (typeof updatePayBtn     === 'function') updatePayBtn();
                if (typeof scheduleAutoSave === 'function') scheduleAutoSave();
            }, true);

            input.addEventListener('keydown', function (e) {
                if (e.ctrlKey || e.metaKey || e.altKey) return;
                var nav = ['Backspace','Delete','ArrowLeft','ArrowRight',
                           'Tab','Home','End','Enter'];
                if (nav.indexOf(e.key) !== -1) return;
                if (!/^\d$/.test(e.key)) {
                    e.preventDefault();
                    e.stopImmediatePropagation();
                    return;
                }
                var wrapper = input.closest ? input.closest('[data-fieldname]') : null;
                if (wrapper) {
                    var max     = getMaxDigits(wrapper);
                    var current = input.value.replace(/\D/g, '');
                    var selLen  = Math.abs(
                        (input.selectionEnd || 0) - (input.selectionStart || 0)
                    );
                    if ((current.length - selLen) >= max) {
                        e.preventDefault();
                        e.stopImmediatePropagation();
                        showLimitAlert(max, wrapper.getAttribute('data-fieldname'));
                    }
                }
            }, true);

            input.addEventListener('keyup', function () { enforceMax(this); }, true);

            input.addEventListener('paste', function (e) {
                e.preventDefault();
                e.stopImmediatePropagation();
                var text    = (e.clipboardData || window.clipboardData).getData('text');
                var wrapper = input.closest ? input.closest('[data-fieldname]') : null;
                var max     = wrapper ? getMaxDigits(wrapper) : 15;
                var clean   = text.replace(/\D/g, '').slice(0, max);
                this.value  = clean;
                this.dispatchEvent(new Event('input', { bubbles: true }));
            }, true);

            input.addEventListener('drop', function (e) {
                e.preventDefault();
                var text    = e.dataTransfer ? e.dataTransfer.getData('text') : '';
                var wrapper = input.closest ? input.closest('[data-fieldname]') : null;
                var max     = wrapper ? getMaxDigits(wrapper) : 15;
                this.value  = text.replace(/\D/g, '').slice(0, max);
                this.dispatchEvent(new Event('input', { bubbles: true }));
            }, true);

            input.addEventListener('blur', function () {
                var result    = enforceMax(this);
                var fieldname = (function () {
                    var el = input.parentNode;
                    while (el) {
                        if (el.getAttribute && el.getAttribute('data-fieldname'))
                            return el.getAttribute('data-fieldname');
                        el = el.parentNode;
                    }
                    return null;
                })();
                if (result.max === 10 && result.value.length > 0 &&
                    result.value.length !== 10) {
                    frappe.msgprint('❌ Indian phone numbers must be exactly 10 digits.');
                    this.value = '';
                    if (fieldname && window.frappe && frappe.web_form) {
                        frappe.web_form.set_value(fieldname, '');
                    }
                }
                if (typeof updatePayBtn === 'function') updatePayBtn();
            }, true);

            var wrapper = input.closest ? input.closest('[data-fieldname]') : null;
            if (wrapper) {
                var flagEl = wrapper.querySelector('.iti_flag, [class*="iti_flag"]');
                if (flagEl) {
                    new MutationObserver(function () {
                        setTimeout(function () { enforceMax(input); }, 150);
                        setTimeout(function () { enforceMax(input); }, 400);
                    }).observe(flagEl, { attributes: true, attributeFilter: ['class'] });
                }
                var flagContainer = wrapper.querySelector(
                    '.iti__flag-container, [class*="flag-container"]'
                );
                if (flagContainer) {
                    flagContainer.addEventListener('click', function () {
                        setTimeout(function () { enforceMax(input); }, 500);
                        setTimeout(function () { enforceMax(input); }, 1000);
                    });
                }
            }

            var _lastVal = '';
            setInterval(function () {
                if (document.activeElement === input) {
                    if (input.value !== _lastVal) {
                        _lastVal = input.value;
                        enforceMax(input);
                    }
                }
            }, 200);

            console.log('[FLE] ✅ Phone v2 bound:', input.name || input.id || 'input',
                '| Current max:', wrapper ? getMaxDigits(wrapper) : '?');
        }

        function findPhoneInput(fieldname) {
            var wrapper = document.querySelector('[data-fieldname="' + fieldname + '"]');
            if (!wrapper) return null;
            var all = wrapper.querySelectorAll('input');
            var best = null;
            for (var i = 0; i < all.length; i++) {
                var t = (all[i].type || '').toLowerCase();
                if (t === 'hidden' || all[i].disabled || all[i].readOnly) continue;
                if (t === 'tel') return all[i];
                if (!best) best = all[i];
            }
            return best;
        }

        function bindAll() {
            PHONE_FIELDS.forEach(function (fn) {
                var inp = findPhoneInput(fn);
                if (inp && !inp.__fle_phone_v2) applyValidation(inp);
            });
        }

        // Force India (+91) as default country for candidate_contact_number
        function setIndiaDefault(fieldname) {
            var wrapper = document.querySelector('[data-fieldname="' + fieldname + '"]');
            if (!wrapper) return false;

            var inputs = wrapper.querySelectorAll('input');

            for (var i = 0; i < inputs.length; i++) {
                var inp = inputs[i];

                // Method 1: intlTelInput global (v17+ static method)
                if (window.intlTelInput && typeof intlTelInput.getInstance === 'function') {
                    try {
                        var inst1 = intlTelInput.getInstance(inp);
                        if (inst1 && typeof inst1.setCountry === 'function') {
                            inst1.setCountry('in');
                            console.log('[FLE] ✅ India set via intlTelInput.getInstance for:', fieldname);
                            return true;
                        }
                    } catch (e) { /* ignore */ }
                }

                // Method 2: intlTelInputGlobals (older versions)
                if (window.intlTelInputGlobals && typeof intlTelInputGlobals.getInstance === 'function') {
                    try {
                        var inst2 = intlTelInputGlobals.getInstance(inp);
                        if (inst2 && typeof inst2.setCountry === 'function') {
                            inst2.setCountry('in');
                            console.log('[FLE] ✅ India set via intlTelInputGlobals for:', fieldname);
                            return true;
                        }
                    } catch (e) { /* ignore */ }
                }

                // Method 3: instance stored directly on element (any key with setCountry)
                try {
                    var eKeys = Object.keys(inp);
                    for (var k = 0; k < eKeys.length; k++) {
                        var eKey = eKeys[k];
                        if (inp[eKey] && typeof inp[eKey].setCountry === 'function') {
                            inp[eKey].setCountry('in');
                            console.log('[FLE] ✅ India set via element[' + eKey + '] for:', fieldname);
                            return true;
                        }
                    }
                } catch (e) { /* ignore */ }
            }

            // Method 4: Frappe fields_dict phone control
            try {
                if (window.frappe && frappe.web_form && frappe.web_form.fields_dict) {
                    var fc = frappe.web_form.fields_dict[fieldname];
                    if (fc) {
                        var itiProps = ['iti', 'phone_input', 'intl_tel_input', 'tel_input'];
                        for (var p = 0; p < itiProps.length; p++) {
                            var iti = fc[itiProps[p]];
                            if (iti && typeof iti.setCountry === 'function') {
                                iti.setCountry('in');
                                console.log('[FLE] ✅ India set via fields_dict.' + itiProps[p] + ' for:', fieldname);
                                return true;
                            }
                        }
                    }
                }
            } catch (e) { /* ignore */ }

            // Method 5: DOM fallback — directly patch the flag element and dial code span
            var flagEl   = wrapper.querySelector('.iti__flag, [class*="iti__flag"]');
            var dialSpan = wrapper.querySelector(
                '.iti__selected-dial-code, .selected-dial-code, [class*="dial-code"]'
            );
            if (flagEl || dialSpan) {
                if (flagEl) {
                    flagEl.className = flagEl.className.replace(/\biti__[a-z]{2}\b/g, '').trim();
                    flagEl.classList.add('iti__in');
                }
                if (dialSpan && !dialSpan.textContent.trim()) {
                    dialSpan.textContent = '+91';
                }
                console.log('[FLE] ✅ India set via DOM fallback for:', fieldname);
                return true;
            }

            return false;
        }

        var _indiaTries = 0;
        function retryIndiaDefault() {
            var done = setIndiaDefault('candidate_contact_number');
            if (!done && _indiaTries++ < 60) setTimeout(retryIndiaDefault, 200);
        }
        retryIndiaDefault();

        var _tries = 0;
        function retryBind() {
            bindAll();
            var done = PHONE_FIELDS.every(function (fn) {
                var inp = findPhoneInput(fn);
                return inp && inp.__fle_phone_v2;
            });
            if (!done && _tries++ < 100) setTimeout(retryBind, 200);
        }
        retryBind();

        new MutationObserver(function () { bindAll(); })
            .observe(document.body || document.documentElement, {
                childList: true, subtree: true
            });

        console.log('[FLE] Phone validation v2 (country-aware, enforce-first) loaded.');
    })();

    // =====================================================
// FIX: Force India (+91) default for candidate contact
// =====================================================

(function () {

    function setIndiaDefault() {

        if (!window.frappe || !frappe.web_form) return false;

        let field = frappe.web_form.fields_dict['candidate_contact_number'];

        if (!field || !field.$input) return false;

        let input = field.$input.get(0);

        if (!input) return false;

        // Wait until intlTelInput initializes
        if (window.intlTelInput && intlTelInput.getInstance) {

            let iti = intlTelInput.getInstance(input);

            if (iti) {
                iti.setCountry('in');
                console.log("🇮🇳 India set as default for candidate_contact_number");
                return true;
            }
        }

        return false;
    }

    function waitForPhoneInit() {

        let done = setIndiaDefault();

        if (!done) {
            setTimeout(waitForPhoneInit, 300);
        }
    }

    // Run after page loads
    window.addEventListener("load", function () {
        setTimeout(waitForPhoneInit, 800);
    });

})();

});

